cat > app/javascript/helpers/date_helpers.js <<'EOF'
export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatDateTime(value, format) {
  const date = parseDate(value, format)

  if (!date || Number.isNaN(date.getTime())) return value

  switch (format) {
    case "relative":
      return formatRelativeDateTime(date)
    case "relative-day":
      return formatRelativeDay(date)
    case "short-date":
      return formatShortDate(date)
    case "full-date":
      return new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit", year: "numeric" }).format(date)
    case "calendar-date":
      return new Intl.DateTimeFormat("en-US", { weekday: "long", month: "long", day: "numeric" }).format(date)
    case "clock":
      return formatClock(date)
    case "date-time":
      return new Intl.DateTimeFormat("en-US", {
        month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit", hour12: true
      }).format(date)
    default:
      return value
  }
}

function parseDate(value, format) {
  if (value instanceof Date) return value

  if (format === "calendar-date" && typeof value === "string") {
    const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/)
    if (match) {
      // Date-only strings parse as UTC; construct this calendar day in the browser's local timezone.
      return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]), 12)
    }
  }

  return new Date(value)
}

function formatRelativeDateTime(date) {
  const days = signedDifferenceInDays(date, new Date())

  if (days === 0) return formatClock(date)
  if (days === 1) return "yesterday"
  if (days === -1) return "tomorrow"
  if (days < 0) return `in ${Math.abs(days)} days`
  if (days < 7) return `${days} days ago`

  return formatShortDate(date)
}

function formatRelativeDay(date) {
  const days = signedDifferenceInDays(date, new Date())

  if (days === 0) return "today"
  if (days === 1) return "yesterday"
  if (days === -1) return "tomorrow"
  if (days > 0) return `${days} days ago`

  return `in ${Math.abs(days)} days`
}

function formatShortDate(date) {
  const options = { month: "short", day: "numeric" }
  if (date.getFullYear() !== new Date().getFullYear()) options.year = "numeric"
  return new Intl.DateTimeFormat("en-US", options).format(date)
}

function formatClock(date) {
  return new Intl.DateTimeFormat("en-US", { hour: "numeric", minute: "2-digit", hour12: true }).format(date)
}
EOF
